(window.TNQ=window.TNQ||[]).push({"terms":{"송수구":{"d":"소방차가 건물 소화배관으로 물을 밀어 넣는 연결구입니다.","r":[]},"감시제어반":{"d":"소화설비의 작동 상태를 감시하고 제어하는 반입니다.","r":["방화구획"]},"방화구획":{"d":"불과 연기가 번지지 않도록 내화 구조의 벽과 문으로 나눈 구역입니다.","r":[]},"방수총":{"d":"멀리까지 대량의 물을 쏘는 고정식 방수 장치입니다.","r":["특수가연물"]},"특수가연물":{"d":"화재가 나면 번지기 쉬워 법령이 수량을 정해 따로 관리하는 가연성 물품입니다.","r":["방수총"]},"스프링클러헤드":{"d":"열을 감지해 물을 흩뿌리는 스프링클러설비의 살수 장치입니다.","r":["차폐판"]},"차폐판":{"d":"위쪽 헤드에서 떨어진 물이 아래 헤드에 닿지 않도록 막는 판입니다.","r":["스프링클러헤드"]},"스트레이너":{"d":"배관 속 이물질을 걸러 내는 여과 장치입니다.","r":["오리피스"]},"오리피스":{"d":"헤드 끝에서 물이 나가는 작은 구멍입니다.","r":["스트레이너"]},"호스릴":{"d":"호스를 릴에 감아 두었다가 풀어서 쓰는 방수 장치입니다.","r":[]},"선택밸브":{"d":"여러 방호구역 가운데 불이 난 구역으로만 약제를 보내도록 여는 밸브입니다.","r":[]},"충전비":{"d":"용기의 내부 용적을 저장한 약제의 무게로 나눈 값입니다.","r":[]},"공칭작동온도":{"d":"정온식감지기가 작동하도록 정해 둔 온도입니다.","r":[]},"경계구역":{"d":"화재가 난 곳을 알아낼 수 있도록 건물을 나눈 최소 감시 단위입니다.","r":[]},"절연저항":{"d":"전기가 도체 밖으로 새지 않게 막는 절연 상태의 저항값입니다.","r":[]},"발신기":{"d":"사람이 직접 눌러 수신기에 화재 신호를 보내는 장치입니다.","r":[]},"단독경보형감지기":{"d":"감지부와 경보부가 한 몸이라 홀로 연기나 열을 감지해 울리는 경보기입니다.","r":[]},"제연구역":{"d":"화재 때 연기를 따로 제어하도록 구획한 범위입니다.","r":[]},"임피던스":{"d":"교류 회로에서 전류가 흐르기 어려운 정도를 나타내는 값입니다.","r":[]},"세장비":{"d":"부재의 길이를 단면 회전반경으로 나눈 값으로 가늘고 긴 정도를 나타냅니다.","r":["상쇄배관"]},"상쇄배관":{"d":"방향을 바꿨다 같은 방향으로 돌아오는 짧은 배관을 직선으로 보는 개념입니다.","r":["세장비"]},"피난유도선":{"d":"피난 방향을 알리려고 바닥이나 벽에 연속으로 켜 두는 유도 표시입니다.","r":[]}},"notes":{"3W(실내에 설치하는 것에 있어서는 1W) 이상일 것":"비상방송 확성기의 음성입력은 3W 이상이고 실내용은 1W 이상이면 됩니다.","3병 이상 설치한 경우에는 2개 이상의 용기에 전자개방밸브를 부착하여야 한다":"가압용 가스용기가 3병 이상이면 그중 2개 이상에 전자개방밸브를 붙입니다.","cm 이하의 위치 또는 바닥 면에 설치할 것":"앞의 높이 기준에 따라 유도선은 이 높이 이하나 바닥 면에 설치해 낮은 곳에서 보이게 합니다.","가압송수장치가 기동되는 경우에는 자동으로 정지되지 아니하도록 하여야 한다":"가압송수장치는 일단 기동하면 저절로 멈추지 않도록 해야 화재 중 물 공급이 이어집니다.","가압용가스에 이산화탄소를 사용하는 것의 이산화탄소는 소화약제 1 kg에 대하여 20 g에 배관의 청소에 필요한 양을 가산한 양 이상으로 할 것":"가압용 이산화탄소 양은 약제 1 kg당 20 g에 배관 청소용 양을 더한 값 이상입니다.","각 실(이웃하는 실내의 바닥면적이 각각 30 m^2 미만이고 벽체의 상부의 전부 또는 일부가 개방되어 이웃하는 실내와 공기가 상호 유통되는 경우에는 이를 1개의 실로 본다)마다 설치하되, 바닥면적이 150 m^2를 초과하는 경우에는 150 m^2마다 1개 이상 설치할 것":"단독경보형감지기는 실마다 달고, 바닥면적이 150 m^2를 넘으면 150 m^2마다 1개 이상 답니다.","각 옥외소화전 5 m 이내에 방수총을 별도로 설치하거나":"방수총은 옥외소화전마다 5미터 이내에 따로 두거나 소화전 겸용품을 설치하면 됩니다.","감지기회로 및 부속회로의 전로와 대지 사이 및 배선 상호간의 절연저항은 1경계구역마다 직류 250 V의 절연저항측정기를 사용하여 측정한 절연저항이 0.1 ㏁ 이상이 되도록 할 것":"감지기회로의 절연저항은 경계구역마다 직류 250 V 측정기로 재어 0.1 ㏁ 이상이어야 합니다.","개폐용 전동모터는 정전 등 전원이 차단되는 경우에도 조작상태를 유지할 수 있도록 할 것":"대배기구 개폐 모터는 정전돼도 열림 닫힘 상태를 유지하도록 만듭니다.","거실과 통로(복도를 포함한다)는 각각 제연구획 할 것":"거실과 통로(복도 포함)는 연기 제어 방식이 달라 각각 제연구획합니다.","건전지를 주전원으로 사용하는 단독경보형감지기는 정상적인 작동상태를 유지할 수 있도록 주기적으로 건전지를 교환할 것":"건전지가 주전원이면 방전으로 작동이 멈출 수 있으니 주기적으로 갈아 줍니다.","공장 또는 창고시설로서 750배":"방수총은 공장이나 창고에서 특수가연물을 750배 이상 저장하거나 취급할 때 설치합니다.","구동장치의 회전 또는 왕복운동으로 소화용수를 가압하여 그 압력으로 급수하는 주된 펌프":"주펌프는 구동장치의 회전이나 왕복운동으로 소화용수에 압력을 주어 급수하는 중심 펌프입니다.","기구의 연결 금속구 등이 없어야 하며 전개된 피난기구는 하강구":"하강구 안쪽에는 피난기구의 연결 금속구 같은 돌출물이 없어야 합니다.","기동용가스용기 및 해당 용기에 사용하는 밸브는 25 MPa 이상의 압력에 견딜 수 있는 것으로 설치해야 한다":"할론설비의 기동용가스용기와 밸브는 25 MPa 이상의 압력을 견디는 제품이어야 합니다.","기동용가스용기의 용적은 1ℓ 이상으로 하고, 해당 용기에 저장하는 이산화탄소의 양은 0.6 kg 이상으로 하며, 충전비는 1.5 이상으로 할 것":"기동용가스용기는 용적 1리터 이상, 이산화탄소 0.6 kg 이상, 충전비 1.5 이상으로 만듭니다.","내력을 충분히 발휘할 수 있도록 견고하게 설치하여야 한다":"버팀대가 설계한 내력을 제대로 내도록 견고하게 고정합니다.","내부면은 두께 0.5 mm 이상의 아연도금강판 또는 동등 이상의 내식성ㆍ내열성이 있는 것으로 마감하되, 접합부에 대하여는 통기성이 없도록 조치할 것":"수직풍도 안쪽은 두께 0.5 mm 이상 아연도금강판이나 그와 같은 내식성·내열성 재료로 마감합니다.","다른 부분과 방화구획을 할 것":"감시제어반을 다른 공간과 방화구획으로 나눠 불이 번져도 제어반이 버티게 합니다.","대피실 내에는 비상조명등을 설치할 것":"대피실 안에는 비상조명등을 두어 정전에도 어둡지 않게 합니다.","대피실에는 층의 위치표시와 피난기구":"대피실에는 층의 위치를 알리는 표시와 피난기구 안내 표지를 붙입니다.","동결방지조치를 하거나 동결의 우려가 없는 장소에 설치할 것":"배관 안의 물이 얼면 막히므로 동결방지조치를 하거나 얼 염려가 없는 곳에 둡니다.","바닥면적은 감시제어반의 설치에 필요한 면적 외에 화재 시 소방대원이 그 감시제어반의 조작에 필요한 최소면적 이상으로 할 것":"제어반 면적은 장비가 들어갈 만큼에 더해, 소방대원이 조작할 최소 공간도 갖추라는 기준입니다.","발신기의 위치표시등은 함의 상부에 설치하되, 그 불빛은 부착 면으로부터 15° 이상의 범위 안에서 부착지점으로부터 10 m 이내의 어느 곳에서도 쉽게 식별할 수 있는 적색등으로 설치해야 한다":"발신기 위치표시등은 함 위쪽에 달고 10 m 이내 어디서나 보이는 적색등이어야 합니다.","방호구역별로 선택밸브 직후 2차측 배관에 설치해야 한다":"방호구역마다 선택밸브 바로 뒤 2차측 배관에 설치한다는 뜻입니다.","방호구역 외의 장소에 설치할 것. 다만, 방호구역 내에 설치할 경우에는 피난 및 조작이 용이하도록 피난구 부근에 설치해야 한다":"분말설비는 방호구역 밖에 두는 것이 원칙이며, 안에 둘 때는 피난구 부근에 두어 조작을 쉽게 합니다.","방호대상물의 각 부분으로부터 하나의 호스릴포방수구까지의 수평거리는 15 m 이하(포소화전방수구의 경우에는 25 m 이하)가 되도록 하고 호스릴 또는 호스의 길이는 방호대상물의 각 부분에 포가 유효하게 뿌려질 수 있도록 할 것":"방호대상물 어디서든 호스릴포방수구까지 15미터 이하(포소화전방수구는 25미터 이하)여야 포가 닿습니다.","배관과 배관이음쇠는 배관용 스테인리스 강관(KS D 3576)의":"옥외소화전 배관과 이음쇠는 배관용 스테인리스 강관, 곧 KS D 3576 규격품을 씁니다.","배관의 측면에 분기호칭내경 이상의 구멍을 뚫고 배관이음쇠를 용접 이음한 배관":"비확관형 분기배관은 배관 옆면에 구멍을 내고 이음쇠를 용접해 붙인 분기 방식입니다.","분말소화약제의 가스용기는 분말소화약제의 저장용기에 접속하여 설치하여야 한다":"분말약제의 가스용기는 분말 저장용기에 직접 접속해 설치합니다.","분배기·분파기 및 혼합기 등의 임피던스는 50Ω의 것으로 할 것":"분배기, 분파기, 혼합기도 임피던스가 50 Ω인 제품을 써서 전체 회로를 맞춥니다.","분배기의 임피던스는 50 Ω의 것으로 할 것":"분배기의 임피던스는 50 Ω으로 맞추어 신호 반사를 줄입니다.","비상전원의 설치장소는 다른 장소와 방화구획 할 것":"비상전원 설치장소는 다른 장소와 방화구획해 화재 때 전원이 살아 있게 합니다.","비상콘센트용의 풀박스 등은 방청도장을 한 것으로서, 두께 1.6밀리미터 이상의 철판으로 할 것":"풀박스는 녹 방지 도장을 하고 두께 1.6밀리미터 이상 철판으로 만듭니다.","사람이 상시 근무하거나 다수인이 출입·통행하는 곳과 자기연소성물질 또는 활성금속물질 등을 저장하는 장소에는 설치해서는 안 된다":"상시 근무자나 다수 출입 장소, 자기연소성물질과 활성금속물질 저장소에는 분사헤드를 달지 않습니다.","사용되는 필터 또는 스트레이너의 메쉬는 헤드 오리피스 지름의 80% 이하가 되어야 한다":"필터나 스트레이너의 메쉬 구멍은 헤드 오리피스 지름의 80퍼센트 이하라야 이물이 헤드를 막지 않습니다.","사용설명서 및 주의사항 표지판을 부착할 것":"피난기구 사용설명서와 주의사항 표지판을 대피실에 붙여 처음 쓰는 사람도 따르게 합니다.","사용 시 기울거나 흔들리지 않도록 설치할 것":"피난기구는 쓸 때 기울거나 흔들리지 않게 고정해 피난자가 안전하게 내려오게 합니다.","살수가 방해되지 아니하도록 벽과 스프링클러헤드간의 공간은 10 cm 이상으로 한다":"벽이 살수를 막지 않도록 벽과 스프링클러헤드 사이는 10센티미터 이상 띄웁니다.","상부에 설치된 헤드의 방출수에 따라 감열부에 영향을 받을 우려가":"위쪽 헤드의 방출수가 아래 헤드 감열부를 식히면 작동이 늦어지므로 차폐판으로 막습니다.","상쇄배관(offset)이란 영향구역 내의 직선배관이 방향전환 한 후 다시 같은 방향으로 연속될 경우, 중간에 방향전환 된 짧은 배관은 단부로 보지 않고 상쇄하여 직선으로 볼 수 있는 것을 말하며, 짧은 배관의 합산길이는 3.7 m 이하여야 한다":"상쇄배관은 방향을 바꿨다 돌아오는 짧은 배관을 직선으로 보는 개념이며, 합산 길이는 3.7 m 이하입니다.","상용전원을 주전원으로 사용하는 단독경보형감지기의 2차전지는 「소방시설 설치 및 관리에 관한 법률」 제40조에 따라 제품검사에 합격한 것을 사용할 것":"상용전원식 단독경보형감지기에 쓰는 2차전지는 제품검사를 통과한 것이어야 합니다.","상호 수평거리 15센티미터 이상의 간격을 둘 것":"착지점과 하강구는 서로 15센티미터 이상 떨어뜨려 피난자가 부딪치지 않게 합니다.","설비에 사용되는 구성요소는 STS 304 이상의 재료를 사용하여야 한다":"미분무 설비의 구성요소는 STS 304 이상의 내식성 재료로 만들어야 합니다.","설치 높이는 천장의 높이가 2 m 이하인 경우에는 천장으로부터 0.15 m 이내의 장소에 설치해야 한다":"시각경보장치는 천장 높이가 2 m 이하이면 천장에서 0.15 m 이내에 답니다.","설치층에서 피난층까지 연계될 수 있는 구조로 설치할 것":"설치 경로는 설치한 층에서 피난층까지 연결되는 구조여야 중간에 끊기지 않습니다.","소방대원의 출입이 가능한 환기구ㆍ작업구마다 지하구의 양쪽방향으로 살수헤드를 설정하되, 한쪽 방향의 살수구역의 길이는 3 m 이상으로 할 것":"지하구 연소방지설비는 출입 가능한 환기구마다 양쪽으로 살수헤드를 두며 한쪽 구역 길이는 3 m 이상입니다.","소화약제 저장용기는 온도가 40℃ 이하이고, 온도변화가 작은 곳에 설치하여야 한다":"약제 저장용기는 온도가 40도 이하이고 온도 변화가 작은 곳에 두어 압력 변동을 줄입니다.","소화약제 저장용기실 내의 소화배관에 설치해야 한다":"설치 위치는 약제 저장용기실 안의 소화배관입니다.","송수구로부터 주배관에 이르는 연결배관에는 개폐밸브를 설치하지 않을 것":"송수구에서 주배관까지 잇는 배관에 밸브가 잠기면 소방차 송수가 끊기기 때문에 두지 않습니다.","송수 및 그 밖의 소화작업에 지장을 주지 않도록 설치할 것":"송수구가 소방차의 물 공급이나 다른 진압 활동을 가로막는 자리에 놓이면 안 됩니다.","수신기가 설치된 장소 등 사람이 상시 근무하는 장소에는 옥외안테나의 위치가 모두 표시된 옥외안테나 위치표시도를 비치할 것":"수신기가 있는 방재실 같은 상시 근무 장소에는 옥외안테나 위치표시도를 비치합니다.","수평투영면적 공간 내의 범위를 침범하지 않는 구조이어야 할 것":"펼친 피난기구가 하강구 수평투영면적 공간 안으로 들어오지 않는 구조여야 합니다.","승강식 피난기 및 하향식 피난구용 내림식사다리는 설치경로가":"승강식 피난기와 하향식 피난구용 내림식사다리는 설치경로가 이어져야 하는 기구입니다.","연기감지기는 아날로그 방식으로 한다":"전기자동차 충전구역의 연기감지기는 연기 농도를 수치로 알리는 아날로그 방식을 씁니다.","옥외소화전과 방수총이 겸용으로 된 것으로 설치할 것":"소화전과 방수총이 한 몸인 겸용 제품을 달면 별도 설치를 대신할 수 있습니다.","옥외소화전까지의 수평거리가 40 m 이하가 되도록 할 것":"수평거리 40미터는 소화전 호스가 건물 모든 부분에 닿게 하려는 거리 한도입니다.","옥외소화전의 호스접결구가 지면으로부터 0.5 m":"호스접결구는 땅에서 0.5미터 높이 이상에 두어 호스를 연결하기 쉽게 합니다.","외기에 면하여 상시 개방된 부분이 있는 차고·주차장·창고 등에 있어서는 외기에 면하는 각 부분으로부터 5 m 미만의 범위 안에 있는 부분은 경계구역의 면적에 산입하지 않는다":"외기에 열린 차고나 창고는 바깥 면에서 5 m 미만인 부분을 경계구역 면적에서 뺍니다.","음량조정기를 설치하는 경우 음량조정기의 배선은 3선식으로 할 것":"음량조정기를 달 때는 배선을 3선식으로 해 조정기가 있어도 경보가 나가게 합니다.","이상 1 m 이하의 높이에 위치하도록 설치할 것":"높이 상한은 1미터이므로 호스접결구는 허리 높이 안팎에 놓이게 됩니다.","이상의 특수가연물을 저장ㆍ취급하는 경우":"특수가연물을 많이 쌓아 두는 곳은 불이 크게 번지므로 방수총을 두어 대비하는 기준입니다.","이음을 용접으로 할 경우 텅스텐 불활성 가스 아크 용접방식에 따른다":"스테인리스 배관을 용접할 때는 텅스텐 불활성 가스 아크 용접 방식을 따라야 합니다.","있는 헤드에는 방출수를 차단할 수 있는 유효한 차폐판을 설치할 것":"차폐판은 위 헤드에서 떨어지는 물을 막아 아래 헤드의 감열부를 보호하는 판입니다.","전원부와 외함 사이를 500볼트 절연저항계로 측정할 때 20메가옴 이상일 것":"비상콘센트 전원부와 외함 사이는 500볼트 절연저항계로 재어 20메가옴 이상입니다.","점검 및 관리가 쉬운 위치에 설치해야 한다":"점검과 관리가 쉬운 곳에 두어야 고장이 나도 바로 손볼 수 있습니다.","제어반등의 하중이 450 N 이하이고 내력벽 또는 기둥에 설치하는 경우 직경 8 mm 이상의 고정용 볼트 4개 이상으로 고정할 수 있다":"제어반 하중이 450 N 이하이고 내력벽이나 기둥에 달 때는 지름 8 mm 이상 볼트 4개 이상으로 고정합니다.","제연설비를 유효하게 60분 이상 작동할 수 있도록 해야 한다":"비상전원은 제연설비가 60분 이상 제 기능을 하도록 전기를 대야 합니다.","조작부의 조작스위치는 바닥으로부터 0.8 m 이상 1.5 m 이하의 높이에 설치할 것":"비상방송 조작부의 스위치도 바닥 위 0.8 m 이상 1.5 m 이하 높이에 둡니다.","조작이 쉬운 장소에 설치하고, 조작스위치는 바닥으로부터 0.8 m 이상 1.5 m 이하의 높이에 설치해야 한다":"발신기는 조작이 쉬운 곳에 두고 조작스위치 높이는 바닥 위 0.8 m 이상 1.5 m 이하입니다.","주방ㆍ보일러실 등으로서 다량의 화기를 취급하는 장소에 설치하되, 공칭작동온도가 최고주위온도보다 20℃ 이상 높은 것으로 설치해야 한다":"정온식감지기는 주방 등 불을 많이 쓰는 곳에 달고 공칭작동온도를 최고주위온도보다 20도 이상 높게 합니다.","주배관은 구경 100 mm 이상, 방수구로 연결되는 배관의 구경은 65 mm 이상인 것으로 하여야 한다":"연결송수관과 배관을 같이 쓰면 주배관은 100밀리미터 이상, 방수구 배관은 65밀리미터 이상이어야 합니다.","증폭기에는 비상전원이 부착된 것으로 하고 해당 비상전원 용량은 무선통신보조설비를 유효하게 30분 이상 작동시킬 수 있는 것으로 할 것":"증폭기에는 비상전원을 붙이고 그 용량은 설비를 30분 이상 작동시킬 정도여야 합니다.","지면으로부터 높이가 0.5미터 이상 1미터 이하의 위치에 설치할 것":"송수구는 땅에서 0.5미터 이상 1미터 이하 높이에 있어야 호스를 쉽게 연결합니다.","지진으로 인한 오동작이 발생하지 않도록 설치하여야 한다":"기동장치와 비상전원은 지진 진동에 오작동하지 않게 설치합니다.","지진하중에 의해 전도가 발생하지 않도록 설치할 것":"저장용기는 지진 하중에 넘어지지 않도록 단단히 고정해 설치합니다.","지하층으로서 특정소방대상물의 바닥부분 2면 이상이 지표면과 동일한 경우에는 해당 층에 한해 설치하지 아니할 수 있다":"지하층 바닥 부분 2면 이상이 지표면과 같은 높이면 그 층만 무선통신보조설비를 생략할 수 있습니다.","창고시설에서 발화한 때에는 전 층에 경보를 발해야 한다":"창고시설에서 불이 나면 한 층만이 아니라 모든 층에 경보를 울려야 합니다.","천장 또는 반자의 옥내에 면하는 부분에 설치할 것. 다만, 지하주차장에 설치하는 감지기의 경우에는 지하주차장의 보의 깊이가 30 cm 이상이고, 보와 보 사이의 내측면 간의 거리가 바닥으로부터 보가 설치된 천장까지의 수직 높이의 40% 이상인 때에는 보로 구획된 부분마다 1개 이상의 감지기를 설치해야 한다":"감지기는 천장이나 반자의 실내 쪽 면에 달며, 지하주차장 보가 깊으면 보로 나뉜 구획마다 둡니다.","축광방식의 피난유도선은 바닥으로부터 높이 50":"축광방식은 빛을 흡수해 두었다가 어둠에서 내는 방식이며, 유도선은 바닥 가까이에 둡니다.","통로상의 제연구역은 보행중심선의 길이가 60 m를 초과하지 않을 것":"통로에 둔 제연구역은 보행중심선 길이가 60 m를 넘지 않아야 합니다.","특정소방대상물의 각 부분으로부터 하나의":"건물 어느 부분에서든 가장 가까운 옥외소화전까지의 수평거리를 제한하는 배치 기준입니다.","특정소방대상물의 층마다 설치하되, 해당 층의 각 부분으로부터 하나의 발신기까지의 수평거리가 25 m 이하가 되도록 설치해야 한다":"발신기는 층마다 두고 층의 어느 곳에서도 하나까지 수평거리가 25 m 이하가 되게 합니다.","파이프덕트 등 그 밖의 이와 비슷한 것으로서 2개층마다 방화구획된 것이나 수평단면적이 5 m^2 이하인 것은 감지기를 설치하지 아니한다":"파이프덕트처럼 2개층마다 방화구획되었거나 수평단면적이 5 m^2 이하이면 감지기를 달지 않습니다.","펌프는 전용으로 할 것(다만, 다른 소화설비와 겸용하는 경우 각각의 소화설비의 성능에 지장이 없을 때에는 그렇지 않음)":"옥내소화전 펌프는 전용이 원칙이고, 다른 설비와 같이 써도 각각의 성능이 유지되면 예외입니다.","펌프의 토출 측 주배관의 구경은 유속이 4 m/s 이하가 될 수 있는 크기 이상으로 하여야 한다":"토출 측 주배관은 물 흐름 속도가 초당 4미터를 넘지 않을 만큼 굵어야 합니다.","펌프의 흡입 측 배관은 공기 고임이 생기지 아니하는 구조로 하고 여과장치를 설치하여야 한다":"흡입 측 배관에 공기가 고이면 물이 제대로 빨려 오지 않아, 이를 막는 구조와 여과장치가 필요합니다.","펌프축은 스테인리스 등 부식에 강한 재질을 사용할 것":"펌프축은 물에 닿아 녹슬기 쉬우므로 스테인리스 같은 내식성 재질로 만듭니다.","포소화전방수구·호스 및 이동식포노즐을 사용하는 설비":"포소화전설비는 포소화전방수구, 호스, 이동식포노즐을 갖춘 포 소화 설비입니다.","피난층 또는 지하 1층에 설치할 것":"감시제어반은 피난층이나 지하 1층에 두어 소방대가 곧바로 접근하게 합니다.","하나의 경계구역의 면적은 600 m^2 이하로 하고 한변의 길이는 50 m 이하로 할 것":"경계구역 하나는 면적 600 m^2 이하, 한 변의 길이 50 m 이하로 정합니다.","하나의 경계구역이 2개 이상의 건축물에 미치지 아니하도록 할 것":"한 경계구역이 두 건축물에 걸치면 어디서 불났는지 알기 어려워 걸치지 못하게 합니다.","하나의 수평직선배관은 최소 2개의 횡방향 흔들림 방지 버팀대와 1개의 종방향 흔들림 방지 버팀대를 설치하여야 한다":"수평직선배관 하나에는 횡방향 버팀대 최소 2개와 종방향 버팀대 1개를 설치합니다.","하나의 전용회로에 설치하는 비상콘센트는 10개 이하로 할 것":"전용회로 하나에 연결하는 비상콘센트는 10개 이하입니다.","하나의 제연구역은 2개 이상 층에 미치지 아니하도록 할 것. 다만, 층의 구분이 불분명한 부분은 그 부분을 다른 부분과 별도로 제연구획 하여야 한다":"제연구역은 2개 이상 층에 걸치지 않게 하되, 층 구분이 불분명한 부분은 따로 제연구획합니다.","하나의 제연구역의 면적은 1,000 m^2 이내로 할 것":"제연구역 하나의 면적은 1,000 m^2 이내로 제한합니다.","헤드간의 수평거리는 개방형스프링클러헤드의 경우에는 1.5 m 이하로 할 것":"연결살수설비에서 개방형 스프링클러헤드끼리 수평거리는 1.5 m 이하로 둡니다.","호스릴 또는 호스를 호스릴포방수구 또는 포소화전방수구로 분리하여 비치하는 때에는 그로부터 3 m 이내의 거리에 호스릴함 또는 호스함을 설치할 것":"호스를 방수구와 따로 보관할 때는 방수구에서 3미터 이내에 호스릴함이나 호스함을 둡니다.","호스릴함 또는 호스함은 바닥으로부터 높이 1.5 m 이하의 위치에 설치하고 그 표면에는 “포호스릴함(또는 포소화전함)”이라고 표시한 표지와 적색의 위치표시등을 설치할 것":"호스릴함은 바닥 위 1.5미터 이하에 두고 표지와 적색 위치표시등을 달아 눈에 띄게 합니다.","화재로 인하여 하나의 층의 지구음향장치 또는 배선이 단락되어도 다른 층의 화재통보에 지장이 없도록 각 층 배선 상에 유효한 조치를 할 것":"한 층의 배선이 단락되더라도 다른 층의 화재 통보는 되도록 층마다 배선에 보호 조치를 합니다.","화재에 노출이 우려되는 제연설비와 전원공급선 및 제트팬 사이의 전원공급장치 등은 250℃의 온도에서 60분 이상 운전상태를 유지할 수 있도록 할 것":"화재에 닿을 수 있는 제연설비 전원공급장치는 250도에서 60분 이상 운전을 유지해야 합니다.","확성기는 각 층마다 설치하되, 그 층의 각 부분으로부터 하나의 확성기까지의 수평거리가 25 m 이하가 되도록 하고, 해당 층의 각 부분에 유효하게 경보를 발할 수 있도록 설치할 것":"확성기는 층마다 두고 수평거리 25 m 이하로 배치해 층 전체에 경보가 들리게 합니다.","환기구 사이의 간격이 700 m를 초과할 경우에는 700 m 이내마다 살수구역을 설정하되, 지하구의 구조를 고려하여 방화벽을 설치한 경우에는 그렇지 않다":"환기구 간격이 700 m를 넘으면 700 m 이내마다 살수구역을 나누고, 방화벽이 있으면 예외입니다.","횡방향 흔들림 방지 버팀대의 간격은 중심선을 기준으로 최대간격이 12 m를 초과하지 않아야 한다":"횡방향 버팀대는 중심선 기준 간격이 최대 12 m를 넘지 않게 둡니다.","흔들림 방지 버팀대가 부착된 건축 구조부재는 소화배관에 의해 추가된 지진하중을 견딜 수 있어야 한다":"버팀대가 붙은 구조부재는 소화배관이 더한 지진하중까지 견뎌야 합니다.","흔들림 방지 버팀대의 세장비(L/r)는 300을 초과하지 않아야 한다":"버팀대의 세장비는 길이 L을 단면 회전반경 r로 나눈 값이며 300을 넘으면 안 됩니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
